class Solution:
    def maxSum(self, grid):
        m,n=len(grid),len(grid[0])
        ans=0
        for i in range(m-2):
            for j in range(n-2):
                s=sum(grid[i][j:j+3])+grid[i+1][j+1]+sum(grid[i+2][j:j+3])
                ans=max(ans,s)
        return ans

