class Solution {
public:
    int maxSum(vector<vector<int>>& g){
        int m=g.size(),n=g[0].size(),ans=0;
        for(int i=0;i+2<m;i++)for(int j=0;j+2<n;j++){
            int s=g[i][j]+g[i][j+1]+g[i][j+2]+g[i+1][j+1]+g[i+2][j]+g[i+2][j+1]+g[i+2][j+2];
            ans=max(ans,s);
        }
        return ans;
    }
};

