class Solution {
    public int maxSum(int[][] g){
        int m=g.length,n=g[0].length,ans=0;
        for(int i=0;i+2<m;i++)for(int j=0;j+2<n;j++)
            ans=Math.max(ans,g[i][j]+g[i][j+1]+g[i][j+2]+g[i+1][j+1]+g[i+2][j]+g[i+2][j+1]+g[i+2][j+2]);
        return ans;
    }
}

